408	      }
409	    },
410	    {
411	      key: 'turnSeconds',
412	      label: '时间限制',
413	      render: function (td, value) {
414	        td.textContent = value === 0 ? '不限时' : value + ' 秒';
415	      }
416	    },
417	    {
418	      key: 'status',
419	      label: '状态',
420	      render: function (td, value) {
421	        appendBadge(td, STATUS_LABELS[value] || value || '');
422	      },
