443	        if (col.renderBad) col.renderBad(td);
444	        else markBadCell(td);
445	      } else {
446	        col.render(td, value);
447	      }
448	      tr.appendChild(td);
449	    });
450	    return tr;
451	  }
452	
453	  function renderRooms(rooms) {
454	    listArea.innerHTML = '';
455	
456	    var validRooms = [];
457	    var skipped = 0;
458	    rooms.forEach(function (r) {
459	      if (isRoomRecord(r)) validRooms.push(r);
460	      else skipped++;
461	    });
462	
463	    if (!validRooms.length) {
464	      if (skipped > 0) {
465	        appendSkipNotice(skipped, true);
466	      } else {
467	        var pEmpty = document.createElement('p');
468	        pEmpty.className = 'empty';
469	        pEmpty.textContent = '还没有房间记录。';
470	        listArea.appendChild(pEmpty);
471	      }
472	      return;
473	    }
474	
475	    if (skipped > 0) appendSkipNotice(skipped, false);
476	
477	    var table = document.createElement('table');
478	    var thead = document.createElement('thead');
479	    var headRow = document.createElement('tr');
