489	      tbody.appendChild(buildRoomRow(r));
490	    });
491	    table.appendChild(tbody);
492	    listArea.appendChild(table);
493	  }
494	
495	  // 列表查询序号：每次发起查询递增，只有当前最新一次查询的结果
496	  // （无论成功还是失败）允许更新列表区域；较早查询后返回的结果一律忽略，
497	  // 防止旧数据覆盖新查询已展示的列表。
498	  var listQuerySeq = 0;
499	
500	  function loadRooms() {
501	    var seq = ++listQuerySeq;
502	    return fetch('/api/rooms', { headers: { 'Accept': 'application/json' } })
503	      .then(function (resp) {
504	        if (!resp.ok) throw new Error('HTTP ' + resp.status);
505	        return resp.json();
506	      })
507	      .then(function (data) {
508	        if (seq !== listQuerySeq) return;
509	        // 读取成功的唯一形态：顶层是 JSON 对象且 rooms 字段是数组。
510	        // 顶层为 null、数组或其他非对象值，缺少 rooms，或 rooms 为
511	        // null、对象、字符串等非数组值时，都按加载失败处理（走下面的
512	        // catch 显示失败提示），绝不能当成空列表显示“还没有房间记录”，
513	        // 也不能把其他内容猜成房间或保留旧表格冒充最新结果。
514	        if (data === null || typeof data !== 'object' || Array.isArray(data) ||
515	            !Array.isArray(data.rooms)) {
516	          throw new Error('房间列表响应格式异常');
517	        }
518	        renderRooms(data.rooms);
519	      })
520	      .catch(function () {
521	        if (seq !== listQuerySeq) return;
522	        listArea.innerHTML = '';
523	        var p = document.createElement('p');
524	        p.className = 'list-error';
525	        p.textContent = '房间列表加载失败，请稍后刷新重试。已有数据不会因此丢失。';
526	        listArea.appendChild(p);
527	      });
528	  }
