      // null、对象、字符串等非数组值时，都按加载失败处理（走下面的
      // catch 显示失败提示），绝不能当成空列表显示“还没有房间记录”，
      // 也不能把其他内容猜成房间或保留旧表格冒充最新结果。
      if (data === null || typeof data !== 'object' || Array.isArray(data) ||
          !Array.isArray(data.rooms)) {
        throw new Error('房间列表响应格式异常');
      }
      renderRooms(data.rooms);
    })
    .catch(function () {
      if (seq !== listQuerySeq) return;
      listArea.innerHTML = '';
      var p = document.createElement('p');
      p.className = 'list-error';
      p.textContent = '房间列表加载失败，请稍后刷新重试。已有数据不会因此丢失。';
      listArea.appendChild(p);
    });
}

