  ], '空对象应作为房间行并沿用现有兜底显示');
  assert.equal(rows[4].badge, '');
  assert.equal(rows[4].timeTitle, null, '缺少创建时间不应附带悬浮说明');
});

// 数组非空但所有元素都是非对象（且刻意包含空串、0、false、空数组这些
