// 即使所有对象行都含异常字段，也要保留表格和这些行：不显示空列表提示，
// 也不显示“全部跳过”的说明（异常对象根本不计入跳过）。
test('所有房间行都含异常字段：保留表格与全部行，无空列表提示、无跳过提示、无加载失败', { timeout: 60000 }, async (t) => {
  const allBad = [
    BAD_NAME,
