  assert.deepEqual(list.emptyTexts, [], '不能把含异常字段的房间当成空列表');
  assert.ok(!list.text.includes(EMPTY_TEXT));

  const rows = await readRows(page);
  assert.equal(rows[0].cells[1], BAD_FIELD_TEXT);
