  assert.deepEqual(rows[1].cells.slice(2, 6), ['五子棋', '2 人', '不限时', '未开始']);
  assert.match(rows[1].cells[6], /^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/);
  // 第三行除编号外的展示字段全部异常：逐格替换，编号仍正常显示。
